// Login.jsx
import React, { useState, useContext } from "react";
import { useNavigate, Link } from "react-router-dom";
import API from "../api";
import { AuthContext } from "../App";

/*
  Redesigned login:
  - Minimal centered panel with soft colors
  - Helpful error messages
  - Comments throughout for clarity
*/

export default function Login() {
  const { setAuth } = useContext(AuthContext);
  const nav = useNavigate();

  // form state
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  // sample helper: demonstrates seeded accounts in UI (non-sensitive)
  const seededHint = "Try: teacher@example.com / Teacher@123 or student@example.com / Student@123";

  const submit = async (e) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      // Call backend login endpoint
      const res = await API.post("/auth/login", { email, password });
      if (res.data.success) {
        // store auth details in localStorage for persistence
        localStorage.setItem("token", res.data.token);
        localStorage.setItem("role", res.data.role);
        localStorage.setItem("userId", res.data.userId);
        setAuth({ token: res.data.token, role: res.data.role, userId: res.data.userId });
        nav("/dashboard");
      } else {
        setErr(res.data.message || "Login failed");
      }
    } catch (error) {
      setErr(error.response?.data?.message || "Network error — check server.");
    } finally {
      setLoading(false);
    }
  };

  // Quick-fill function to demonstrate seeded accounts (not required)
  const quickFillTeacher = () => {
    setEmail("teacher@example.com");
    setPassword("Teacher@123");
  };
  const quickFillStudent = () => {
    setEmail("student@example.com");
    setPassword("Student@123");
  };

  return (
    <div className="app-container" style={{maxWidth:880}}>
      <div className="header">
        <div>
          <div className="brand">
            <div className="logo">ET</div>
            <div>
              <h3 className="h-title">EdTech Task Manager</h3>
              <div className="h-sub">Minimal dashboard for teachers & students</div>
            </div>
          </div>
        </div>
        <div className="small">Secure · Lightweight · Role-based</div>
      </div>

      <div className="login-wrap">
        {/* LEFT: login form */}
        <div className="login-panel">
          <h2 style={{marginTop:0}}>Welcome back</h2>
          <p className="small">Sign in to continue to your dashboard.</p>

          <form className="form" onSubmit={submit}>
            <label className="small">Email</label>
            <input className="input" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@domain.com" />

            <label className="small">Password</label>
            <input className="input" type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your password" />

            {err && <div style={{color:"#b91c1c", fontWeight:600}}>{err}</div>}

            <div style={{display:"flex", gap:10, marginTop:6}}>
              <button className="btn btn-primary" type="submit" disabled={loading}>
                {loading ? "Signing in…" : "Sign in"}
              </button>
              <button type="button" className="btn btn-ghost" onClick={quickFillTeacher}>Use Teacher</button>
              <button type="button" className="btn btn-ghost" onClick={quickFillStudent}>Use Student</button>
            </div>

            <div style={{marginTop:8}} className="small">
              {seededHint}
            </div>
          </form>

          <div style={{marginTop:14}} className="small">
            New? <Link to="/signup">Create an account</Link>
          </div>
        </div>

        {/* RIGHT: illustration / quick stats */}
        <div className="login-illustration">
          <div style={{textAlign:"center", maxWidth:260}}>
            <svg width="120" height="120" viewBox="0 0 24 24" fill="none" style={{marginBottom:12}}>
              <rect x="1" y="3" width="22" height="18" rx="3" fill="#e6f3f1"/>
              <path d="M4 7h16" stroke="#0f766e" strokeWidth="1.2" />
              <circle cx="8" cy="13" r="1.6" fill="#0f766e"/>
              <rect x="10" y="11" width="8" height="2" rx="1" fill="#bfe9e4"/>
            </svg>
            <div style={{fontWeight:700}}>Clean & Focused</div>
            <div className="small" style={{marginTop:8}}>Quickly view tasks, update progress and collaborate with your class.</div>
          </div>
        </div>
      </div>
    </div>
  );
}
